277	/* --- 蛇形展开布局：文字换行式游标推进，距离严格保留，超界折行并从对侧继续 --- */
278	function serpentineCoords(list, rowW) {
279	  const coords = new Map();
280	  if (!list.length) return { coords, rowCount: 0 };
281	  const scale = tlExpanded ? tlZoom : 1;
282	  const left = 100, right = 40 + rowW - 100;   // 两侧各留 100px，保证卡片完整显示在浏览器内
283	  let row = 0, dir = 1, prevX = left, prevPos = list[0].position;
284	  list.forEach((p, i) => {
285	    let x;
286	    if (i === 0) {
287	      x = left;
288	    } else {
289	      x = prevX + dir * (p.position - prevPos) * scale;
290	      if (dir === 1 && x > right) { row++; dir = -1; x = right - (x - right); }   // 右溢 → 折行，从右端回退溢出量
291	      else if (dir === -1 && x < left) { row++; dir = 1; x = left + (left - x); } // 左溢 → 折行，从左端前进溢出量
292	      x = clamp(x, left, right);
293	    }
294	    coords.set(p.id, { x, y: row * ROW_H + 120, row });
295	    prevX = x; prevPos = p.position;
296	  });
297	  return { coords, rowCount: row + 1, scale };
298	}
