303	  let ghost = track.querySelector('.ghost-rowline');
304	  if (!ghost) { ghost = document.createElement('div'); ghost.className = 'ghost-rowline'; track.appendChild(ghost); }
305	  let slot = track.querySelector('.ghost-slot');
306	  if (!slot) { slot = document.createElement('div'); slot.className = 'ghost-slot'; track.appendChild(slot); }
307	  return { ghost, slot };
