309	function showGhost(top, left = null) {
310	  const { ghost, slot } = ghostLine();
311	  const rRaw = Math.round((top - 120) / ROW_H);
312	  const r = clamp(rRaw, 0, tlRowCount);
313	  ghost.style.top = (r * ROW_H + 120) + 'px';
314	  ghost.classList.toggle('new-row', rRaw >= tlRowCount);   // 末行之下：提示将排到时间线末尾
315	  ghost.classList.add('on');
316	  if (left !== null) {
317	    slot.style.left = clamp(left, 40, ($('#timeline-scroll').clientWidth - 40)) + 'px';
318	    slot.style.top = (r * ROW_H + 120) + 'px';
319	    slot.classList.add('on');
320	  }
321	}
