328	/* --- 展开模式落点：纵向吸附最近的行轴线；横向按落点在两邻居间线性插值为时间位置 --- */
329	function expandedDropPosition(selfId, dropLeft, dropTop) {
330	  const placed = filteredPassages().filter(p => Number.isFinite(p.position)).sort((a, b) => a.position - b.position);
331	  const scroll = $('#timeline-scroll');
332	  const rowW = Math.max(420, scroll.clientWidth - 120);
333	  const { coords, rowCount } = serpentineCoords(placed, rowW);
334	  const tail = () => Math.max(0, (placed.length ? Math.max(...placed.map(p => p.position)) : 0) + 160);
335	  const rRaw = Math.round((dropTop - 120) / ROW_H);
336	  if (rRaw >= rowCount) return { position: tail(), row: rowCount };   // 末行之下 → 排到时间线最后
337	  const r = clamp(rRaw, 0, rowCount - 1);
338	  const rowY = r * ROW_H + 120;
339	  const rowClips = placed
340	    .filter(p => p.id !== selfId && Math.abs(coords.get(p.id).y - rowY) < 1)
341	    .sort((a, b) => coords.get(a.id).x - coords.get(b.id).x);
342	  if (!rowClips.length) return { position: tail(), row: r };
343	  const xs = rowClips.map(p => coords.get(p.id).x);
344	  const ps = rowClips.map(p => p.position);
345	  // 找落点两侧（按行内 x 排序）的邻居，线性插值；越界则用最近一对外推
346	  let i = xs.findIndex(x => x > dropLeft);
347	  if (i === -1) i = xs.length - 1;
348	  const i0 = Math.max(0, i - 1), i1 = Math.min(xs.length - 1, i);
349	  let pos;
350	  if (xs[i1] === xs[i0]) pos = ps[i0];
351	  else pos = ps[i0] + (dropLeft - xs[i0]) * (ps[i1] - ps[i0]) / (xs[i1] - xs[i0]);
352	  pos = Math.round(pos);
353	  // 不与邻居完全重合：向落点一侧错开 1 个单位
354	  if (rowClips.some(p => p.position === pos)) {
355	    const side = i1 < xs.length - 1 ? 1 : -1;
356	    pos = Math.max(0, pos + side);
357	    if (rowClips.some(p => p.position === pos)) pos = Math.max(0, pos - 2 * side);
358	  }
359	  return { position: pos, row: r };
360	}
