363	function renderTimeline() {
364	  const all = filteredPassages();
365	  const placed = all.filter(p => Number.isFinite(p.position)).sort((a, b) => a.position - b.position);
366	  const unplaced = all.filter(p => !Number.isFinite(p.position));
367	  const track = $('#timeline-track');
368	  const scroll = $('#timeline-scroll');
369	  renderPool(unplaced);
370	  $('#timeline-result').textContent = `显示 ${placed.length} 个 clips` + (unplaced.length ? `，${unplaced.length} 个未入线` : '');
371	  $('#timeline-range').textContent = placed.length ? (placed[0].date || '未标时间') + ' — ' + (placed.at(-1).date || '未标时间') : 'NO ENTRIES YET';
372	  $('#tl-zoom').textContent = Math.round(tlZoom * 100) + '%';
373	  $('#timeline-expand').textContent = tlExpanded ? '收起' : '展开';
374	  track.classList.toggle('expanded', tlExpanded);
375	  scroll.style.overflowY = tlExpanded ? 'auto' : 'hidden';
376	  scroll.style.maxHeight = '';
377	  scroll.style.height = '';
378	
379	  if (!placed.length) {

379	  if (!placed.length) {
380	    timeNodeEls.clear();
381	    track.style.width = '100%'; track.style.height = '100%';
382	    track.innerHTML = '<div class="time-axis"></div><div class="timeline-empty">还没有符合条件的 clips</div>';
383	    $('#timeline-list').innerHTML = emptyHTML('时间线上还没有 clips', '在码字页添加一个分节，然后从未入线区域拖入时间线。', '＋');
384	    $('#interval-panel').classList.add('hidden');
385	    return;
386	  }
387	
388	  const z = tlExpanded ? 1 : tlZoom;
389	  let coords = new Map(), rowCount = 1, rowW = 0;
390	  if (tlExpanded) {
391	    rowW = Math.max(420, scroll.clientWidth - 120);
392	    const s = serpentineCoords(placed, rowW);
393	    coords = s.coords; rowCount = s.rowCount;
394	  } else {
395	    placed.forEach(p => coords.set(p.id, { x: 40 + p.position * z, y: scroll.clientHeight / 2 }));
396	  }
