347	/* --- 展开模式落点：纵向吸附最近的行轴线；横向按落点在两邻居间线性插值为时间位置 --- */
348	function expandedDropPosition(selfId, dropLeft, dropTop) {
349	  const placed = filteredPassages().filter(p => Number.isFinite(p.position)).sort((a, b) => a.position - b.position);
350	  const scroll = $('#timeline-scroll');
351	  const rowW = Math.max(420, scroll.clientWidth - 120);
352	  const { coords, rowCount } = serpentineCoords(placed, rowW);
353	  const tail = () => Math.max(0, (placed.length ? Math.max(...placed.map(p => p.position)) : 0) + 160);
354	  const rRaw = Math.round((dropTop - 120) / ROW_H);
355	  if (rRaw >= rowCount) return { position: tail(), row: rowCount };   // 末行之下 → 排到时间线最后
356	  const r = clamp(rRaw, 0, rowCount - 1);
357	  const rowY = r * ROW_H + 120;
358	  const rowClips = placed
359	    .filter(p => p.id !== selfId && Math.abs(coords.get(p.id).y - rowY) < 1)
360	    .sort((a, b) => coords.get(a.id).x - coords.get(b.id).x);
361	  if (!rowClips.length) return { position: tail(), row: r };
362	  const xs = rowClips.map(p => coords.get(p.id).x);
363	  const ps = rowClips.map(p => p.position);
364	  // 找落点两侧（按行内 x 排序）的邻居，线性插值；越界则用最近一对外推
365	  let i = xs.findIndex(x => x > dropLeft);
366	  if (i === -1) i = xs.length - 1;
367	  const i0 = Math.max(0, i - 1), i1 = Math.min(xs.length - 1, i);
368	  let pos;
369	  if (xs[i1] === xs[i0]) pos = ps[i0];
370	  else pos = ps[i0] + (dropLeft - xs[i0]) * (ps[i1] - ps[i0]) / (xs[i1] - xs[i0]);
371	  pos = Math.round(pos);
372	  // 不与邻居完全重合：向落点一侧错开 1 个单位
373	  if (rowClips.some(p => p.position === pos)) {
374	    const side = i1 < xs.length - 1 ? 1 : -1;
375	    pos = Math.max(0, pos + side);
376	    if (rowClips.some(p => p.position === pos)) pos = Math.max(0, pos - 2 * side);
377	  }
378	  return { position: pos, row: r };
379	}
