19	function loadDB() {
20	  let d = null;
21	  try { d = JSON.parse(localStorage.getItem(KEY)); } catch {}
22	  if (!d || !Array.isArray(d.stories) || !Array.isArray(d.passages)) {
23	    d = { stories: [], passages: [], characters: [], clues: [], links: [], hiddenLinks: [], timeRelations: [] };
24	  }
25	  d.characters ||= []; d.clues ||= []; d.links ||= []; d.hiddenLinks ||= []; d.timeRelations ||= [];
26	  d.prefs ||= {};
27	  // 迁移①：角色分类 主角/配角 → 神/人类/动物/其他
28	  const kindMap = { major: 'human', supporting: 'other' };
29	  d.characters.forEach(c => { if (kindMap[c.kind]) c.kind = kindMap[c.kind]; if (!KINDS[c.kind]) c.kind = 'human'; });
30	  // 迁移②：clip 的 role 同步映射
31	  d.passages.forEach(p => (p.characters || []).forEach(x => { if (kindMap[x.role]) x.role = kindMap[x.role]; }));
32	  // 迁移③：字符串 tags → 线索库 clueIds
33	  d.passages.forEach(p => {
34	    if (Array.isArray(p.tags)) {
35	      p.tags.forEach(name => {
36	        const n = String(name).trim(); if (!n) return;
37	        let clue = d.clues.find(c => c.name === n);
38	        if (!clue) { clue = { id: id(), name: n, description: '' }; d.clues.push(clue); }
39	        (p.clueIds ||= []).includes(clue.id) || p.clueIds.push(clue.id);
40	      });
41	      delete p.tags;
42	    }
43	    p.clueIds ||= []; p.section ||= 'body'; p.characters ||= [];
44	  });
45	  return d;
